/// Triple DES ECB encryption (SP 800-38A §6.1) of `n` complete 8-byte blocks at `data`, in place, under the schedule written by `vg_triple_des_expand_key`. No padding is added or removed. For `n = 0`, no data is transformed.
///
/// Contract: `VG.Spec.TripleDes.ecbEncryptContract`. Constant time: only pointers and `n` may affect timing, not the schedule or data.
///
/// Baseline x86-64, calling the verified Triple DES block primitive for each complete block.
///
/// # Safety
///
/// * `schedule` must be valid for reads of 384 bytes.
/// * `data` must be valid for reads and writes of `8 * n` bytes.
/// * `scratch` must be valid for reads and writes of 1024 bytes.
/// * The contents of `scratch` on return are unspecified.
/// * `data` and `scratch` must not overlap each other or `schedule` (distinct Rust objects never do).
/// * None of `schedule`, `data` and `scratch` may overlap the return address on the stack or the 8 bytes of stack below it, or wrap around the end of the address space (no Rust object does).
#[unsafe(naked)]
pub(crate) unsafe extern "sysv64" fn vg_triple_des_ecb_encrypt(schedule: *const [u8; 384], data: *mut [u8; 8], n: usize, scratch: *mut [u64; 128]) {
    core::arch::naked_asm!(
        "mov QWORD PTR [rcx+512], rbp",
        "mov rbp, rdx",
        "mov rdx, rcx",
        "cmp rbp, 0",
        "je 20f",
        "22:",
        "call {vg_triple_des_encrypt_block}",
        "add rsi, 8",
        "sub rbp, 1",
        "jne 22b",
        "jmp 21f",
        "20:",
        "21:",
        "mov rbp, QWORD PTR [rdx+512]",
        "ret",
        vg_triple_des_encrypt_block = sym super::triple_des::vg_triple_des_encrypt_block,
    )
}

